<?php
declare(strict_types=1);
require_once __DIR__.'/config/erp.php';
$pdo=srnu_db();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(isset($_POST['guardar'])){
            $id=(int)($_POST['id']??0);$nombre=epost('nombre');$telefono=epost('telefono');$email=epost('email');$notas=epost('notas');
            if($nombre===''||srnu_normalizar_telefono($telefono)==='')throw new RuntimeException('Nombre y teléfono son obligatorios.');
            srnu_guardar_cliente($nombre,$telefono,$id,$email,$notas);ego('clientes.php?ok=1');
        }
        if(isset($_POST['toggle'])){$pdo->prepare('UPDATE clientes SET activo=IF(activo=1,0,1) WHERE id=?')->execute([(int)$_POST['id']]);ego('clientes.php');}
    }catch(Throwable $e){$error=$e->getMessage();}
}
$edit=null;if(($id=(int)($_GET['edit']??0))){$edit=srnu_obtener_cliente($id);}
$q=trim((string)($_GET['q']??''));
$sql="SELECT cl.*, COUNT(c.id) cotizaciones, COALESCE(SUM(c.total),0) total_cotizado, MAX(c.fecha) ultima_cotizacion FROM clientes cl LEFT JOIN cotizaciones c ON c.cliente_id=cl.id";
$params=[];if($q!==''){$sql.=" WHERE cl.nombre LIKE ? OR cl.telefono LIKE ?";$params=['%'.$q.'%','%'.$q.'%'];}
$sql.=" GROUP BY cl.id ORDER BY cl.activo DESC,cl.nombre";$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clientes · SRNU Custom</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('clientes');?><main class="w"><div class="srnu-page-heading"><div><h1>Registro de clientes</h1><p>Nombre y teléfono quedan disponibles para reutilizarlos en cualquier cotización.</p></div><a class="btn blue" href="cotizador.php">＋ Nueva cotización</a></div><?php if($error):?><div class="srnu-error"><?=eh($error)?></div><?php elseif(isset($_GET['ok'])):?><div class="srnu-ok">Cliente guardado correctamente.</div><?php endif;?><section class="panel" style="padding:18px"><div class="section-title"><h2><?=$edit?'Editar cliente':'Agregar cliente'?></h2></div><form method="post" class="erp-form cols-4"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div><label>Nombre</label><input name="nombre" required autocomplete="name" value="<?=eh($edit['nombre']??'')?>" placeholder="Nombre del cliente"></div><div><label>Teléfono</label><input name="telefono" required inputmode="tel" autocomplete="tel" value="<?=eh($edit['telefono']??'')?>" placeholder="871 000 0000"></div><div><label>Email (opcional)</label><input type="email" name="email" value="<?=eh($edit['email']??'')?>" placeholder="correo@ejemplo.com"></div><div><label>Notas (opcional)</label><input name="notas" value="<?=eh($edit['notas']??'')?>" placeholder="Preferencias o referencia"></div><div class="toolbar full"><button class="btn blue" name="guardar" value="1"><?=$edit?'Guardar cambios':'＋ Agregar cliente'?></button><?php if($edit):?><a class="btn light" href="clientes.php">Cancelar</a><?php endif;?></div></form></section><section class="filters" style="margin-top:16px"><form method="get" style="display:flex;gap:8px;width:100%;flex-wrap:wrap"><input style="flex:1;min-width:240px" name="q" value="<?=eh($q)?>" placeholder="Buscar por nombre o teléfono"><button class="btn blue">Buscar</button><?php if($q!==''):?><a class="btn light" href="clientes.php">Limpiar</a><?php endif;?></form></section><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Cliente</th><th>Teléfono</th><th>Email</th><th>Cotizaciones</th><th>Total cotizado</th><th>Última</th><th>Acciones</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="muted" style="padding:24px;text-align:center">No hay clientes registrados.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr style="<?=$r['activo']?'':'opacity:.5'?>"><td><b><?=eh($r['nombre'])?></b><?php if(!$r['activo']):?><div><span class="badge badge-red">Inactivo</span></div><?php endif;?></td><td><?=eh($r['telefono'])?></td><td><?=eh($r['email']?:'—')?></td><td><?=(int)$r['cotizaciones']?></td><td><?=emoney($r['total_cotizado'])?></td><td><?=edate($r['ultima_cotizacion'])?></td><td><div class="toolbar"><a class="btn blue" href="cotizador.php?cliente_id=<?=$r['id']?>">Nueva cotización</a><a class="btn light" href="?edit=<?=$r['id']?>">Editar</a><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn <?=$r['activo']?'danger':'green'?>" name="toggle" value="1"><?=$r['activo']?'Desactivar':'Activar'?></button></form></div></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
